 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate a palette encoded as identical adjacent rows containing a
    # left-to-right list of colors (with zero padding around it).
    palette = None
    r = 0
    while r < h - 1:
        if grid[r] == grid[r + 1]:
            end = r + 1
            while end + 1 < h and grid[end + 1] == grid[r]:
                end += 1
            colors = [v for v in grid[r] if v != 0]
            if len(colors) >= 2:
                palette = (r, end, colors)
                break
            r = end + 1
        else:
            r += 1
    if palette is None:
        raise ValueError('repeated-row color palette not found')
    p_top, p_bottom, colors = palette

    # Extract the connected color-1 figure as the reusable motif.
    seen = set()
    components = []
    for rr in range(h):
        for cc in range(w):
            if grid[rr][cc] != 1 or (rr, cc) in seen:
                continue
            stack = [(rr, cc)]
            seen.add((rr, cc))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 1 and (ny,nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            components.append(comp)
    if not components:
        raise ValueError('color-1 motif not found')
    motif = max(components, key=len)
    r0 = min(y for y, _ in motif)
    c0 = min(x for _, x in motif)
    mh = max(y for y, _ in motif) - r0 + 1
    offsets = [(y-r0, x-c0) for y, x in motif]

    # Keep the original color-1 copy at its palette position and stamp the
    # other palette colors above/below it. The palette itself is removed.
    one_index = colors.index(1)
    first_top = r0 - one_index * mh
    out = [row[:] for row in grid]
    for y in range(p_top, p_bottom + 1):
        for x in range(w):
            out[y][x] = 0
    for i, color in enumerate(colors):
        for dy, dx in offsets:
            y, x = first_top + i * mh + dy, c0 + dx
            if 0 <= y < h and 0 <= x < w:
                out[y][x] = color
    return out
